mapper.update:
UPDATE application_target
SET tie_order = #{tieOrder},
    updated_at = #{updatedAt}
WHERE id = #{targetId}

mapper.select:
SELECT COUNT(*)
FROM application_target t
JOIN volunteer_application va ON va.id = t.application_id
WHERE t.teacher_id = #{teacherId}
  AND va.round_no = #{roundNo}
  AND t.score = #{score}
  AND t.tie_order = #{tieOrder}
  AND t.id <> #{targetId}

SELECT COUNT(*)
FROM final_admission
WHERE teacher_id = #{teacherId}

SELECT COUNT(*)
FROM offer
WHERE teacher_id = #{teacherId}
  AND status = 'PENDING'
  AND confirm_deadline > #{now}

SELECT COUNT(*)
FROM offer
WHERE application_target_id = #{targetId}

mapper.insert:
INSERT INTO offer (
    teacher_id, student_id, application_target_id, round_no, status,
    confirm_deadline, granted_at
) VALUES (
